<?php
declare(strict_types=1);
function people_password_schema(): PDO {$db=team_db();$db->exec("CREATE TABLE IF NOT EXISTS password_recovery(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,created_at TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS password_reset_tokens(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,token_hash TEXT UNIQUE NOT NULL,version TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS recovery_rate(ip_hash TEXT PRIMARY KEY,started INTEGER NOT NULL,count INTEGER NOT NULL)");return $db;}
function people_password_validate($password,$confirmation): string {if(!is_string($password)||strlen($password)<12||strlen($password)>72)throw new RuntimeException('Mật khẩu mới cần 12–72 ký tự.',400);if(!is_string($confirmation)||!hash_equals($password,$confirmation))throw new RuntimeException('Hai mật khẩu mới chưa khớp.',400);return password_hash($password,PASSWORD_DEFAULT);}
function people_password_change(array $data): void {
 $u=team_identity();if(!$u)throw new RuntimeException('Vui lòng đăng nhập.',401);$old=$data['current_password']??null;if(!is_string($old))throw new RuntimeException('Cần mật khẩu hiện tại.',400);$hash=people_password_validate($data['new_password']??null,$data['confirmation']??null);$version=bin2hex(random_bytes(16));
 if($u['owner']){$lock=fopen(admin_private().'/admin-config.lock','c');chmod(admin_private().'/admin-config.lock',0600);if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Chưa đổi được mật khẩu.',500);try{$config=admin_config();if(!hash_equals($config['version'],$_SESSION['auth_version'])||!password_verify($old,$config['password_hash']))throw new RuntimeException('Mật khẩu hiện tại chưa đúng.',400);$config['password_hash']=$hash;$config['version']=$version;$tmp=tempnam(admin_private(),'auth-');chmod($tmp,0600);try{if(file_put_contents($tmp,json_encode($config,JSON_THROW_ON_ERROR))===false||!rename($tmp,admin_private().'/admin-config.json'))throw new RuntimeException('Chưa lưu được mật khẩu.',500);}finally{if(is_file($tmp))unlink($tmp);}}finally{flock($lock,LOCK_UN);fclose($lock);}people_audit('password_change',$u['username'],[],null,$u);
 }else{$db=team_db();$q=$db->prepare('SELECT password_hash,version FROM staff WHERE id=?');$q->execute([$u['id']]);$row=$q->fetch();if(!$row||!password_verify($old,$row['password_hash']))throw new RuntimeException('Mật khẩu hiện tại chưa đúng.',400);$db->beginTransaction();try{$q=$db->prepare('UPDATE staff SET password_hash=?,version=? WHERE id=? AND version=?');$q->execute([$hash,$version,$u['id'],$row['version']]);if(!$q->rowCount())throw new RuntimeException('Tài khoản vừa thay đổi. Vui lòng đăng nhập lại.',409);people_audit('password_change',$u['username'],[],null,$u);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}}
 $_SESSION['auth_version']=$version;$_SESSION['csrf']=bin2hex(random_bytes(32));session_regenerate_id(true);
}
function people_recovery_request(string $username,string $phone): void {
 $db=people_password_schema();$ip=hash('sha256','victor-recovery:'.($_SERVER['REMOTE_ADDR']??'unknown'));$q=$db->prepare('SELECT * FROM recovery_rate WHERE ip_hash=?');$q->execute([$ip]);$rate=$q->fetch();$now=time();if($rate&&$now-(int)$rate['started']<900&&(int)$rate['count']>=5)throw new RuntimeException('Vui lòng chờ 15 phút trước khi gửi lại.',429);$within=$rate&&$now-(int)$rate['started']<900;$db->prepare('INSERT INTO recovery_rate(ip_hash,started,count) VALUES(?,?,?) ON CONFLICT(ip_hash) DO UPDATE SET started=excluded.started,count=excluded.count')->execute([$ip,$within?$rate['started']:$now,$within?(int)$rate['count']+1:1]);
 $q=$db->prepare('SELECT id,username,phone FROM staff WHERE username=?');$q->execute([$username]);$row=$q->fetch();if(!$row||admin_phone_key($row['phone'])===''||!hash_equals(admin_phone_key($row['phone']),admin_phone_key($phone)))return;
 $q=$db->prepare('SELECT 1 FROM password_recovery WHERE user_id=? AND resolved=0');$q->execute([$row['id']]);if($q->fetchColumn())return;$db->prepare('INSERT INTO password_recovery(user_id,created_at) VALUES(?,?)')->execute([$row['id'],gmdate('c')]);people_audit('password_reset_request',$row['username'],['verified'=>false],null,['id'=>0,'username'=>'system','name'=>'Yêu cầu chưa xác minh']);
}
function people_recovery_list(): array {people_require_owner();return people_password_schema()->query('SELECT r.id,r.user_id,r.created_at,s.username,s.name FROM password_recovery r JOIN staff s ON s.id=r.user_id WHERE r.resolved=0 ORDER BY r.id DESC LIMIT 100')->fetchAll();}
function people_reset_issue(int $id): string {
 people_require_owner();if($id<1)throw new RuntimeException('Chỉ cấp liên kết cho tài khoản nhân viên.',400);$db=people_password_schema();$q=$db->prepare('SELECT username,version FROM staff WHERE id=?');$q->execute([$id]);$u=$q->fetch();if(!$u)throw new RuntimeException('Không tìm thấy nhân viên.',404);$raw=bin2hex(random_bytes(32));$db->beginTransaction();try{$db->prepare('UPDATE password_reset_tokens SET used=1 WHERE user_id=?')->execute([$id]);$db->prepare('INSERT INTO password_reset_tokens(user_id,token_hash,version,expires) VALUES(?,?,?,?)')->execute([$id,hash('sha256',$raw),$u['version'],time()+1800]);$db->prepare('UPDATE password_recovery SET resolved=1 WHERE user_id=?')->execute([$id]);people_audit('password_reset_issue',$u['username'],['expiresMinutes'=>30]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}return 'https://thevictor.vn/quan-tri/password.php?token='.$raw;
}
function people_reset_grant(string $raw): string {if(!preg_match('/^[a-f0-9]{64}$/D',$raw))throw new RuntimeException('Liên kết không hợp lệ.',400);$hash=hash('sha256',$raw);$q=people_password_schema()->prepare('SELECT 1 FROM password_reset_tokens t JOIN staff s ON s.id=t.user_id WHERE t.token_hash=? AND t.used=0 AND t.expires>=? AND t.version=s.version');$q->execute([$hash,time()]);if(!$q->fetchColumn())throw new RuntimeException('Liên kết hết hạn hoặc đã sử dụng. Liên hệ quản trị viên để cấp lại.',400);return $hash;}
function people_reset_password(string $grant,array $data): void {
 $hash=people_password_validate($data['new_password']??null,$data['confirmation']??null);$db=people_password_schema();$db->beginTransaction();try{$q=$db->prepare('SELECT t.id,t.user_id,t.version,s.username FROM password_reset_tokens t JOIN staff s ON s.id=t.user_id WHERE t.token_hash=? AND t.used=0 AND t.expires>=? AND t.version=s.version');$q->execute([$grant,time()]);$row=$q->fetch();if(!$row)throw new RuntimeException('Liên kết hết hạn hoặc đã sử dụng.',400);$db->prepare('UPDATE staff SET password_hash=?,version=? WHERE id=? AND version=?')->execute([$hash,bin2hex(random_bytes(16)),$row['user_id'],$row['version']]);$db->prepare('UPDATE password_reset_tokens SET used=1 WHERE user_id=?')->execute([$row['user_id']]);people_audit('password_reset_complete',$row['username'],[],null,['id'=>(int)$row['user_id'],'username'=>$row['username'],'name'=>$row['username']]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
}
